//! iterative_search_pdb: DPAM step 7's loop with Fortran semantics.

use dali_core::pipeline::{dpam_domain_ranges, iterative_search_pdb, PdbIterParams};
use dali_core::ProteinStore;

const V: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../validation");

/// Cases generated by DPAM's own get_domain_range (dpam_c2 step07), incl. the
/// boundary where a gap equals the cutoff exactly.
#[test]
fn test_domain_ranges_match_dpam() {
    let text = std::fs::read_to_string(format!("{}/dpam/get_domain_range_cases.txt", V)).unwrap();
    let mut n = 0;
    for line in text.lines() {
        let (input, want) = line.split_once('|').unwrap();
        let resids: Vec<i32> = input.split(',').map(|x| x.parse().unwrap()).collect();
        let got: Vec<String> = dpam_domain_ranges(&resids).iter().map(|(a, b)| format!("{}-{}", a, b)).collect();
        assert_eq!(got.join(","), want, "input {}", input);
        n += 1;
    }
    assert!(n >= 40);
}

fn gunzip(path: &str) -> String {
    use std::io::Read;
    let mut s = String::new();
    flate2::read::GzDecoder::new(std::fs::File::open(path).unwrap()).read_to_string(&mut s).unwrap();
    s
}

/// Two-domain AF query against one of its own domains as template: round 0 finds
/// it, masking removes the aligned span, and every later round's query is a fresh
/// import of the remaining ATOM records (never containing removed residues).
#[test]
fn test_iterative_search_pdb_masks_and_reimports() {
    let dir = std::env::temp_dir().join(format!("dali_iterpdb_{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let store = ProteinStore::new(&dir);
    let query = gunzip(&format!("{}/puu/afq4A/afq4A.pdb.gz", V));
    // template: residues 1-200 of the same model
    let templ: String = query.lines()
        .filter(|l| l.starts_with("ATOM") && l[22..26].trim().parse::<i32>().unwrap() <= 200)
        .map(|l| format!("{}\n", l)).collect();
    let t = dali_core::io::import_pdb_text(&templ, "A", "templ01").unwrap();
    store.add_protein(t).unwrap();

    let hits = iterative_search_pdb(&query, "A", "query01", &["templ01"], &store, &PdbIterParams::default()).unwrap();
    assert!(!hits.is_empty());
    let h0 = &hits[0];
    assert!(h0.zscore > 20.0, "self-match Z {}", h0.zscore);
    assert_eq!(h0.qlen, 442);
    assert!(h0.query_resids.iter().all(|&r| r >= 1 && r <= 442));
    let removed = dpam_domain_ranges(&h0.query_resids);
    for h in &hits[1..] {
        for r in &h.query_resids {
            assert!(!removed.iter().any(|&(a, b)| *r >= a && *r <= b), "round {} aligned removed residue {}", h.round, r);
        }
        assert!(h.qlen < h0.qlen);
    }
    for (k, h) in hits.iter().enumerate() {
        assert_eq!(h.round, k);
        let q = store.get_protein(&format!("query01_r{}", k)).unwrap();
        assert_eq!(q.resid_map.len(), q.nres);
    }
    let _ = std::fs::remove_dir_all(&dir);
}
